<section class="detail-section episode-section" id="episoade"><div class="section-head"><div><h2>Sezoane și episoade</h2><p>Alege un sezon pentru a vedea episoadele disponibile.</p></div><label class="season-selector">Sezon<select id="seasonSelect" aria-label="Alege sezonul"><?php foreach($seasons as $i=>$season):?><option value="season-<?=$i?>"<?=(int)$season['season']===$selectedSeason?' selected':''?>>Sezonul <?=(int)$season['season']?> · <?=count((array)($season['episodes_data']??[]))?> episoade</option><?php endforeach;?></select></label></div>
<?php foreach($seasons as $i=>$season):$sn=(int)$season['season'];$active=$sn===$selectedSeason;?><section class="season-panel" id="season-<?=$i?>" data-season="<?=$sn?>"<?=$active?'':' hidden data-pending="true"'?> aria-label="Sezonul <?=$sn?>"><?php if($active):$seasonEpisodes=(array)($season['episodes_data']??[]);include __DIR__.'/episode-list.php';else:?><p class="season-status" role="status">Episoadele se încarcă la selectarea sezonului.</p><?php endif;?></section><?php endforeach;?>
<noscript><p>Alege sezonul: <?php foreach($seasons as $season):?><a href="<?=e(title_path($titleItem))?>?sezon=<?=(int)$season['season']?>#episoade">Sezonul <?=(int)$season['season']?></a> <?php endforeach;?></p></noscript></section>
